using System;using System.IO;using System.Text;using System.Drawing;using System.Linq;using System.Collections.Generic;
namespace GearLab {
 public static class FullDrawingExport {
  public const double PxPerMm=96.0/25.4;
  static string F(double n){return n.ToString("0.#########",System.Globalization.CultureInfo.InvariantCulture);}
  static string Q(string s){return "\""+s.Replace("\"","\"\"")+"\"";}
  public static void Write(CadAssembly model,string type,string file){if(!model.Valid)throw new Exception("Полная 3D-модель не построена: "+string.Join(";",model.Errors));if(type=="csv"){Csv(model,file);return;}List<SketchLoop> loops;List<SketchCircle> circles;Flat(model,out loops,out circles);if(type=="svg")Svg(loops,circles,file);else if(type=="dxf")Dxf(loops,circles,file);else throw new Exception("Неизвестный формат деталей.");}
  static string Signature(CadPart p){double x=p.Sections[0].Outer.Bounds()[0],y=p.Sections[0].Outer.Bounds()[2],z=p.Sections[0].Bottom;Func<double,string> n=v=>v.ToString("0.####",System.Globalization.CultureInfo.InvariantCulture);Func<CadLoop,string> l=h=>h.Circle?"C"+n(h.X-x)+","+n(h.Y-y)+","+n(h.R):"P"+string.Join(";",h.Points.Select(v=>n(v.X-x)+","+n(v.Y-y)));return p.Role+"|"+string.Join("|",p.Sections.Select(s=>n(s.Bottom-z)+":"+n(s.Top-z)+":"+l(s.Outer)+":"+string.Join("/",s.Holes.Select(l))));}
  static IEnumerable<IGrouping<string,CadPart>> Groups(CadAssembly model){return model.Parts.Where(p=>!p.Reference).GroupBy(Signature);}
  public static void Flat(CadAssembly model,out List<SketchLoop> loops,out List<SketchCircle> circles){
   loops=new List<SketchLoop>();circles=new List<SketchCircle>();var groups=Groups(model).ToList();int columns=Math.Max(1,(int)Math.Ceiling(Math.Sqrt(groups.Count)));double x=0,y=0,rowH=0;int index=0;
   foreach(var group in groups){var part=group.First();var sections=part.Sections;double minX=sections.Min(s=>s.Outer.Bounds()[0]),maxX=sections.Max(s=>s.Outer.Bounds()[1]),minY=sections.Min(s=>s.Outer.Bounds()[2]),maxY=sections.Max(s=>s.Outer.Bounds()[3]);double dx=x-minX,dy=y-minY;string prefix=part.Id+"_Q"+group.Count();var seen=new HashSet<string>();
    for(int k=0;k<sections.Count;k++){var s=sections[k];foreach(var contour in new[]{s.Outer}.Concat(s.Holes)){if(!seen.Add(contour.Key()))continue;var moved=contour.Move(dx,dy);string name=prefix+"_Z"+Engine.N(s.Bottom-sections[0].Bottom)+"_TO_"+Engine.N(s.Top-sections[0].Bottom);if(moved.Circle)circles.Add(new SketchCircle(name,moved.X,moved.Y,moved.R));else loops.Add(new SketchLoop(name,moved.Points));}}
    rowH=Math.Max(rowH,maxY-minY);x+=maxX-minX+12;index++;if(index%columns==0){x=0;y+=rowH+12;rowH=0;}
   }
  }
  public static void Svg(List<SketchLoop> loops,List<SketchCircle> circles,string file){var points=loops.SelectMany(s=>s.Points).ToList();foreach(var c in circles){points.Add(new PointF((float)(c.X-c.R),(float)(c.Y-c.R)));points.Add(new PointF((float)(c.X+c.R),(float)(c.Y+c.R)));}if(points.Count==0)throw new Exception("Нет контуров для SVG.");double x0=points.Min(v=>v.X)-3,y0=points.Min(v=>v.Y)-3,w=points.Max(v=>v.X)-x0+3,h=points.Max(v=>v.Y)-y0+3,k=PxPerMm;var b=new StringBuilder();
   b.AppendLine("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\""+F(w)+"mm\" height=\""+F(h)+"mm\" viewBox=\""+F(x0*k)+" "+F((-y0-h)*k)+" "+F(w*k)+" "+F(h*k)+"\">");b.AppendLine("<title>GearLab 1.3; physical mm; SVG coordinates at 96 dpi. Check calibration_10mm.svg after Fusion import.</title><metadata>mm_to_svg_px="+F(k)+"; use STEP for 3D assembly</metadata><g transform=\"scale(1,-1)\" fill=\"none\" stroke-width=\""+F(.12*k)+"\">");
   for(int j=0;j<loops.Count;j++){var s=loops[j];b.Append("<polygon id=\""+s.Name.Replace('.','_')+"_"+j+"\" stroke=\"#126eaa\" points=\"");foreach(var v in s.Points)b.Append(F(v.X*k)+","+F(v.Y*k)+" ");b.AppendLine("\"/>");}
   for(int j=0;j<circles.Count;j++){var c=circles[j];b.AppendLine("<circle id=\""+c.Name.Replace('.','_')+"_"+j+"\" cx=\""+F(c.X*k)+"\" cy=\""+F(c.Y*k)+"\" r=\""+F(c.R*k)+"\" stroke=\"#4b7e91\"/>");}b.AppendLine("</g></svg>");ReleaseSupport.WriteText(file,b.ToString(),Encoding.UTF8);
  }
  public static void Calibration(string file){var l=new List<SketchLoop>{new SketchLoop("CALIBRATION_10MM",new[]{new PointF(0,0),new PointF(10,0),new PointF(10,10),new PointF(0,10)})};Svg(l,new List<SketchCircle>(),file);}
  public static void Dxf(List<SketchLoop> loops,List<SketchCircle> circles,string file){var b=new StringBuilder("0\r\nSECTION\r\n2\r\nHEADER\r\n9\r\n$ACADVER\r\n1\r\nAC1015\r\n9\r\n$INSUNITS\r\n70\r\n4\r\n0\r\nENDSEC\r\n0\r\nSECTION\r\n2\r\nENTITIES\r\n");foreach(var s in loops){b.Append("0\r\nLWPOLYLINE\r\n100\r\nAcDbEntity\r\n8\r\n"+s.Name.Replace('.','_')+"\r\n100\r\nAcDbPolyline\r\n90\r\n"+s.Points.Length+"\r\n70\r\n1\r\n");foreach(var v in s.Points)b.Append("10\r\n"+F(v.X)+"\r\n20\r\n"+F(v.Y)+"\r\n");}foreach(var c in circles)b.Append("0\r\nCIRCLE\r\n100\r\nAcDbEntity\r\n8\r\n"+c.Name.Replace('.','_')+"\r\n100\r\nAcDbCircle\r\n10\r\n"+F(c.X)+"\r\n20\r\n"+F(c.Y)+"\r\n30\r\n0\r\n40\r\n"+F(c.R)+"\r\n");b.Append("0\r\nENDSEC\r\n0\r\nEOF\r\n");ReleaseSupport.WriteText(file,b.ToString(),Encoding.ASCII);}
  public static void Csv(CadAssembly model,string file){var b=new StringBuilder("Деталь;Количество;Сечения / размеры;Примечание\r\n");foreach(var group in Groups(model)){var p=group.First();b.AppendLine(Q(p.Id+" · "+p.Label)+";"+group.Count()+";"+Q(string.Join(" | ",p.Sections.Select(s=>"Z "+Engine.F(s.Bottom-p.Sections[0].Bottom)+".."+Engine.F(s.Top-p.Sections[0].Bottom)+" мм; "+(s.Outer.Circle?"Ø"+Engine.F(2*s.Outer.R):"профиль")+"; отверстий "+s.Holes.Count)))+";"+Q(p.Note??"Геометрическая деталь; посадки и прочность проверить"));}foreach(string note in model.Notes)b.AppendLine(Q("Допущение")+";;"+Q(note)+";");foreach(string error in model.Errors)b.AppendLine(Q("ОШИБКА")+";;"+Q(error)+";");var dims=model.Bounds();b.AppendLine(Q("Полный габарит")+";;"+Q(Engine.F(dims[1]-dims[0])+" × "+Engine.F(dims[3]-dims[2])+" × "+Engine.F(dims[5]-dims[4])+" мм")+";");ReleaseSupport.WriteText(file,b.ToString(),new UTF8Encoding(true));}
 }
}
